    ("昭和", "S", date(1926, 12, 25), 1926),
    ("大正", "T", date(1912, 7, 30), 1912),
    ("明治", "M", date(1873, 1, 0), 1868),
]
_FULL = str.maketrans("０１２３４５６７８９", "0123456789")
_KANJI_RE = re.compile(r"\s*(令和|平成|昭和|大正|明治)\s*(元|[0-9０-９]+)\s*年\s*([0-9０-９]+)\s*月\s*([0-9０-９]+)\s*日\s*")
